    "U1-I09": {
      "title": "Visiting Coober Pedy · TEQ adaptation",
      "lines": [
        "It took me three days to reach Coober Pedy. The nearest town was 400 miles away. My first night as a travel writer here? A bed in a hole in the ground, without even wi-fi. So much for glamour.",
        "On my map it was a town in the South Australian desert, 1,800 miles from Canberra, the capital of Australia. Through the windscreen it could have been Mars.",
        "Red dust ran to the horizon. Against it stood hills of white soil; between them, holes left by mining broke up the ground.",
        "Otherworldly was the word that came to me. There was something unnerving about looking out across country where nothing looked quite familiar.",
        "Summer here felt hotter than the Sun, winter colder than Mars. I began to understand why people made their homes underground in dugouts.",
        "In the 1920s people came hoping to make a fortune from opals. They blasted and dug for the stones, finding ways to live with the heat in order to keep working.",
        "At the edge of town I imagined an empty film set, ready for a Martian adventure. Someone had cast me as its heroine without even asking.",
        "Still, the red dust and those mine shafts looked wonderful in my photos."
      ]
    },
    "U1-I10": {
      "title": "Mandora · TEQ language example",
      "lines": [
        "At midday I looked down the street in Mandora. Heat haze hung between me and the houses.",
        "The town seemed underwater. Each figure crossing the road wavered and rippled, as though swimming through the light."
      ]
    },
    "U1-I11": {
      "title": "Living under the ground · TEQ adaptation",
      "lines": [
        "After all that red earth and those empty-looking mine shafts, I had a question for someone who actually lived in Coober Pedy. How did she manage here?",
        "Alinta rolled her eyes. She was seventeen and helped run her parents’ tourist dugout. Next year she would be in Melbourne studying computing.",
        "“We're underground, not down at the Earth's core!” she laughed. “Did you think we had no electricity?” I suspect she gets tired of people arriving with that idea.",
        "Some of the family's electricity came from solar power. For the rest, they used diesel. The diesel was expensive; paying guests at the dugout helped meet the bills.",
        "I thought them inventive. They used what they had, watched their electricity use and counted on travellers being curious enough to stay.",
        "People came chiefly for the town's mining history. What would draw them here in 2060? How long could a community keep going in such a place?",
        "Back in my apartment in Canberra, I spread my photographs of the red countryside across the table.",
        "Outside came the drone of traffic; beside me, the constant pinging of my phone. Those familiar sounds seemed alien now.",
        "Perhaps a quiet home under the ground had rather more to offer than I'd thought."
      ]
    },
